import {drawTeams} from './draw.js';
const $=id=>document.getElementById(id);let teamText='';let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado! Pronto para compartilhar.')}catch{toast('Não foi possível copiar. Selecione o texto e copie manualmente.')}}
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.open).showModal()));
document.querySelectorAll('dialog').forEach(d=>{d.querySelectorAll('.close,.close-action').forEach(b=>b.addEventListener('click',()=>d.close()));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('date').min=today;$('date').value=today;$('year').textContent=new Date().getFullYear();
$('booking-form').addEventListener('submit',e=>{e.preventDefault();if($('date').value<today){toast('Escolha uma data a partir de hoje.');return}const date=$('date').value.split('-').reverse().join('/');$('message').value=`Olá! Gostaria de consultar ${$('resource').value.toLowerCase()} no Acadêmicos para ${date}, às ${$('time').value} (horário de Brasília), por ${$('duration').value.toLowerCase()}. Podem informar disponibilidade, valor e condições? Entendo que esta solicitação não confirma reserva nem pagamento.`;$('request-result').hidden=false;$('message').focus()});
$('copy-request').addEventListener('click',()=>copy($('message').value));
$('draw-form').addEventListener('submit',e=>{e.preventDefault();try{const result=drawTeams($('players').value.split('\n'),Number($('team-count').value),Number($('capacity').value));$('teams').replaceChildren();let lines=[];[...result.teams,...(result.reserves.length?[result.reserves]:[])].forEach((players,i)=>{const title=i<result.teams.length?`Time ${i+1}`:'Reservas';const card=document.createElement('section');card.className='team';const h=document.createElement('h3');h.textContent=title;const list=document.createElement('ul');players.forEach(name=>{const li=document.createElement('li');li.textContent=name;list.append(li)});card.append(h,list);$('teams').append(card);lines.push(title+'\n'+players.join('\n'))});teamText=lines.join('\n\n');$('draw-status').textContent=`Sorteio local concluído. ${result.missing?`Faltam ${result.missing} atletas para completar a capacidade.`:'Times com capacidade completa.'} ${result.reserves.length?`${result.reserves.length} na reserva.`:''} Confira os goleiros antes de jogar.`;$('copy-teams').hidden=false}catch(err){$('draw-status').textContent=err.message;$('teams').replaceChildren();$('copy-teams').hidden=true;teamText=''}});
$('copy-teams').addEventListener('click',()=>copy(teamText));
